var t=`0778-ubugali`;var n=`world-0778`;var s=`BI`;var r=`eastern-africa`;var a=8;var o=42;var l={en:`Ubugali`,ua:`Убугалі`};var g={en:`Ubugali is a Burundi classic prepared with cornmeal. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Убугалі, страва кухні країни Бурунді зі складниками: кукурудзяна крупа дрібного помелу. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var u=[{en:`Cook the listed ingredients in simmering water for about 9 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 9 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:9,i:[[`water`,1e3,`ml`],[`table-salt`,5,`g`]]},{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 21 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 21 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:21,i:[[`cornmeal`,390,`g`]]},{en:`Roll or press the prepared dough evenly into the desired thickness and shape.`,ua:`Розкачайте або розпластайте підготовлене тісто рівномірним шаром потрібної товщини та форми.`,t:[`pressing`,`rolling-out-dough`],m:9,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`unsalted-butter`,35,`g`]]}];var d={slug:t,id:n,country:`BI`,region:r,servings:8,minutes:42,title:l,text:g,steps:u};export{s as country,d as default,n as id,o as minutes,r as region,a as servings,t as slug,u as steps,g as text,l as title};